package ae.notify;

import java.util.Optional;

/** A delivery channel: strategy that renders a notification into its wire line. */
public interface Channel {
    /** Lower-case registry name, e.g. {@code sms}. */
    String name();

    /** Whether the channel is muted during quiet hours for non-high priorities. */
    boolean respectsQuietHours();

    /** Renders the notification line. */
    String render(Notification n);

    /** Looks up a built-in channel by its normalised (trimmed, lower-case) name. */
    static Optional<Channel> byName(String name) {
        return Channels.find(name);
    }
}

package ae.notify;

import java.util.List;
import java.util.Optional;

/** Built-in channel strategies. */
final class Channels {
    private Channels() {}

    static final Channel EMAIL = new Channel() {
        public String name() { return "email"; }
        public boolean respectsQuietHours() { return false; }
        public String render(Notification n) {
            String prefix = switch (n.priority()) {
                case HIGH -> "[URGENT] ";
                case LOW -> "[FYI] ";
                case NORMAL -> "";
            };
            return "EMAIL to=" + n.user() + " subject=" + prefix + Text.orDefault(n.title(), "(no subject)")
                    + " body=" + n.body();
        }
    };

    static final Channel SMS = new Channel() {
        public String name() { return "sms"; }
        public boolean respectsQuietHours() { return true; }
        public String render(Notification n) {
            String text = n.title().isEmpty() ? n.body()
                    : n.body().isEmpty() ? n.title() : n.title() + ": " + n.body();
            if (n.priority() == Priority.HIGH) {
                text = "!! " + text;
            }
            return "SMS to=" + n.user() + " text=" + Text.truncate(text, 160);
        }
    };

    static final Channel PUSH = new Channel() {
        public String name() { return "push"; }
        public boolean respectsQuietHours() { return true; }
        public String render(Notification n) {
            String sound = switch (n.priority()) {
                case HIGH -> "alarm";
                case NORMAL -> "default";
                case LOW -> "none";
            };
            return "PUSH to=" + n.user() + " title=" + Text.truncate(Text.orDefault(n.title(), "(no title)"), 40)
                    + " body=" + Text.truncate(n.body(), 100) + " sound=" + sound;
        }
    };

    static final Channel SLACK = new Channel() {
        public String name() { return "slack"; }
        public boolean respectsQuietHours() { return false; }
        public String render(Notification n) {
            String text = "*" + Text.orDefault(n.title(), "(no title)") + "*";
            if (!n.body().isEmpty()) {
                text += "\n" + n.body();
            }
            if (n.priority() == Priority.HIGH) {
                text = ":rotating_light: " + text;
            }
            return "SLACK to=#" + n.user() + " text=" + text;
        }
    };

    private static final List<Channel> ALL = List.of(EMAIL, SMS, PUSH, SLACK);

    static Optional<Channel> find(String name) {
        return ALL.stream().filter(c -> c.name().equals(name)).findFirst();
    }
}

package ae.notify;

import java.util.Locale;
import java.util.Map;
import java.util.Optional;

/** Validation and policy (preferences, quiet hours) around channel rendering. Guard order matches the legacy code. */
final class Dispatcher {
    private static final int QUIET_FROM = 22;
    private static final int QUIET_UNTIL = 7;

    private Dispatcher() {}

    static Outcome dispatch(String channel, String priority, String user, String title, String body,
                            int hour, Map<String, String> prefs) {
        if (channel == null || channel.isBlank()) {
            return new Outcome.Failed("no-channel");
        }
        String channelName = channel.trim().toLowerCase(Locale.ROOT);
        if (user == null || user.isBlank()) {
            return new Outcome.Failed("no-user");
        }
        Priority prio = Priority.NORMAL;
        if (priority != null) {
            Optional<Priority> parsed = Priority.parse(priority);
            if (parsed.isEmpty()) {
                return new Outcome.Failed("bad-priority");
            }
            prio = parsed.get();
        }
        if (hour < 0 || hour > 23) {
            return new Outcome.Failed("bad-hour");
        }
        Optional<Channel> found = Channel.byName(channelName);
        if (found.isEmpty()) {
            return new Outcome.Failed("unknown-channel:" + channelName);
        }
        Channel ch = found.get();
        if (isDisabled(prefs, channelName)) {
            return new Outcome.Skipped("disabled");
        }
        if (ch.respectsQuietHours() && isQuiet(hour) && prio != Priority.HIGH) {
            return new Outcome.Skipped("quiet-hours");
        }
        Notification n = new Notification(user.trim(), prio, title == null ? "" : title, body == null ? "" : body);
        return new Outcome.Sent(ch.render(n));
    }

    private static boolean isDisabled(Map<String, String> prefs, String channelName) {
        if (prefs == null) {
            return false;
        }
        String pref = prefs.get(channelName);
        return pref != null && pref.trim().equalsIgnoreCase("off");
    }

    private static boolean isQuiet(int hour) {
        return hour >= QUIET_FROM || hour < QUIET_UNTIL;
    }
}

package ae.notify;

import java.util.Objects;

/** A validated notification: recipient trimmed, title/body never null. */
public record Notification(String user, Priority priority, String title, String body) {
    public Notification {
        Objects.requireNonNull(user);
        Objects.requireNonNull(priority);
        Objects.requireNonNull(title);
        Objects.requireNonNull(body);
    }
}

package ae.notify;

import java.util.Map;

/** Facade with the legacy signature: renders one notification to its wire string. */
public final class Notifier {
    private Notifier() {}

    /**
     * Renders a notification.
     *
     * @return {@code ERR:...} for invalid input, {@code SKIP:...} when suppressed, otherwise the channel line
     */
    public static String render(String channel, String priority, String user, String title, String body,
                                int hour, Map<String, String> prefs) {
        return Dispatcher.dispatch(channel, priority, user, title, body, hour, prefs).text();
    }

    /** Same as {@link #render} but returns the typed outcome. */
    public static Outcome dispatch(String channel, String priority, String user, String title, String body,
                                   int hour, Map<String, String> prefs) {
        return Dispatcher.dispatch(channel, priority, user, title, body, hour, prefs);
    }
}

package ae.notify;

/** Result of dispatching one notification; {@link #text()} is the legacy wire string. */
public sealed interface Outcome {
    String text();

    /** Rejected input, e.g. {@code ERR:no-user}. */
    record Failed(String code) implements Outcome {
        public String text() { return "ERR:" + code; }
    }

    /** Intentionally not sent, e.g. {@code SKIP:disabled}. */
    record Skipped(String reason) implements Outcome {
        public String text() { return "SKIP:" + reason; }
    }

    /** Rendered message line. */
    record Sent(String line) implements Outcome {
        public String text() { return line; }
    }
}

package ae.notify;

import java.util.Locale;
import java.util.Optional;

/** Message priority; parsing keeps the legacy "trim, lower-case, exact match" rule. */
public enum Priority {
    LOW, NORMAL, HIGH;

    /** Parses a user-supplied priority; empty if it is not one of low/normal/high. */
    public static Optional<Priority> parse(String raw) {
        switch (raw.trim().toLowerCase(Locale.ROOT)) {
            case "low": return Optional.of(LOW);
            case "normal": return Optional.of(NORMAL);
            case "high": return Optional.of(HIGH);
            default: return Optional.empty();
        }
    }
}

package ae.notify;

/** Shared text helpers (the legacy code copy-pasted these). */
final class Text {
    private Text() {}

    /** Cuts to {@code max} chars by keeping {@code max-3} and appending "..." when longer than max. */
    static String truncate(String s, int max) {
        return s.length() > max ? s.substring(0, max - 3) + "..." : s;
    }

    static String orDefault(String s, String fallback) {
        return s.isEmpty() ? fallback : s;
    }
}

