package ae.notify;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.util.Map;
import org.junit.jupiter.api.Test;

/** Literal expectations; run against both the legacy oracle and the refactored facade. */
class CharacterisationTest {
    interface Impl {
        String render(String ch, String pr, String user, String title, String body, int hour, Map<String, String> prefs);
    }

    static final Impl LEGACY = LegacyNotifier::render;
    static final Impl REFACTORED = Notifier::render;

    private static final String L160 = "x".repeat(160);

    static void table(Impl i) {
        // validation
        assertEquals("ERR:no-channel", i.render(null, "high", "u", "t", "b", 12, null));
        assertEquals("ERR:no-channel", i.render("  ", "bogus", null, "t", "b", 99, null));
        assertEquals("ERR:no-user", i.render("email", "bogus", " ", "t", "b", 99, null));
        assertEquals("ERR:bad-priority", i.render("email", " urgent ", "u", "t", "b", 99, null));
        assertEquals("ERR:bad-hour", i.render("nope", "low", "u", "t", "b", 24, null));
        assertEquals("ERR:bad-hour", i.render("email", null, "u", "t", "b", -1, null));
        assertEquals("ERR:unknown-channel:fax", i.render(" FAX ", null, "u", "t", "b", 9, null));
        // prefs
        assertEquals("SKIP:disabled", i.render("Email", "high", "u", "t", "b", 3, Map.of("email", " OFF ")));
        assertEquals("EMAIL to=u subject=t body=b", i.render("email", null, " u ", "t", "b", 9, Map.of("email", "on")));
        assertEquals("EMAIL to=u subject=t body=b", i.render("email", null, "u", "t", "b", 9, Map.of("sms", "off")));
        // quiet hours: 22..6 skip sms/push unless high; email/slack unaffected
        assertEquals("SKIP:quiet-hours", i.render("sms", "normal", "u", "t", "b", 22, null));
        assertEquals("SKIP:quiet-hours", i.render("push", "low", "u", "t", "b", 6, null));
        assertEquals("PUSH to=u title=t body=b sound=none", i.render("push", "low", "u", "t", "b", 7, null));
        assertEquals("SMS to=u text=t: b", i.render("sms", null, "u", "t", "b", 21, null));
        assertEquals("SMS to=u text=!! t: b", i.render("sms", "HIGH", "u", "t", "b", 23, null));
        assertEquals("EMAIL to=u subject=[FYI] t body=b", i.render("email", "low", "u", "t", "b", 0, null));
        assertEquals("SLACK to=#u text=*t*\nb", i.render("slack", null, "u", "t", "b", 2, null));
        // email
        assertEquals("EMAIL to=u subject=(no subject) body=", i.render("email", null, "u", null, null, 9, null));
        assertEquals("EMAIL to=u subject=[URGENT] (no subject) body=b", i.render("email", "high", "u", "", "b", 9, null));
        // sms composition and truncation at the 160 boundary
        assertEquals("SMS to=u text=b", i.render("sms", null, "u", "", "b", 9, null));
        assertEquals("SMS to=u text=t", i.render("sms", null, "u", "t", "", 9, null));
        assertEquals("SMS to=u text=", i.render("sms", null, "u", null, null, 9, null));
        assertEquals("SMS to=u text=" + L160, i.render("sms", null, "u", "", L160, 9, null));
        assertEquals("SMS to=u text=" + "x".repeat(157) + "...", i.render("sms", null, "u", "", L160 + "y", 9, null));
        assertEquals("SMS to=u text=!! " + "x".repeat(154) + "...", i.render("sms", "high", "u", "", L160, 9, null));
        // push truncation: title 40 / body 100, sound by priority
        assertEquals("PUSH to=u title=" + "t".repeat(40) + " body=" + "b".repeat(100) + " sound=default",
                i.render("push", null, "u", "t".repeat(40), "b".repeat(100), 9, null));
        assertEquals("PUSH to=u title=" + "t".repeat(37) + "... body=" + "b".repeat(97) + "... sound=alarm",
                i.render("push", "high", "u", "t".repeat(41), "b".repeat(101), 3, null));
        assertEquals("PUSH to=u title=(no title) body= sound=default", i.render("push", null, "u", null, null, 9, null));
        // slack
        assertEquals("SLACK to=#u text=*(no title)*", i.render("slack", null, "u", "", "", 9, null));
        assertEquals("SLACK to=#u text=:rotating_light: *t*\nb", i.render("slack", "high", "u", "t", "b", 9, null));
        assertEquals("SLACK to=#u text=*(no title)*\nb", i.render("slack", "low", "u", "", "b", 9, null));
    }

    @Test
    void legacyMatchesTable() {
        table(LEGACY);
    }

    @Test
    void refactoredMatchesTable() {
        table(REFACTORED);
    }

}

package ae.notify;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;

/** Exhaustive grid of edge values: refactored facade must equal the legacy oracle on every combination. */
class DifferentialTest {
    private static final List<String> CHANNELS = java.util.Arrays.asList(
            null, "", "  ", "email", " EMAIL ", "Sms", "push", "SLACK", "fax", " Fax ");
    private static final List<String> PRIOS = java.util.Arrays.asList(
            null, "", "low", " HIGH ", "Normal", "urgent");
    private static final List<String> USERS = java.util.Arrays.asList(null, "", " ", "bob", " bob ");
    private static final List<String> TEXTS = java.util.Arrays.asList(
            null, "", "t", "t".repeat(39), "t".repeat(40), "t".repeat(41), "m".repeat(98), "m".repeat(100),
            "m".repeat(101), "m".repeat(157), "m".repeat(158), "m".repeat(160), "m".repeat(161), "a\nb");
    private static final int[] HOURS = {-1, 0, 6, 7, 12, 21, 22, 23, 24};
    private static final List<Map<String, String>> PREFS = java.util.Arrays.asList(
            null, Map.of(), Map.of("email", "off"), Map.of("sms", " Off "), Map.of("push", "on"),
            Map.of("slack", "OFF", "email", "off"));

    @Test
    void gridMatchesLegacy() {
        int checked = 0;
        for (String ch : CHANNELS) for (String pr : PRIOS) for (String u : USERS)
            for (String title : TEXTS) for (int h : HOURS) for (Map<String, String> p : PREFS) {
                String body = TEXTS.get((title == null ? 0 : title.length()) % TEXTS.size());
                String ctx = "ch=" + ch + " pr=" + pr + " u=" + u + " title=" + title + " h=" + h + " prefs=" + p;
                assertEquals(LegacyNotifier.render(ch, pr, u, title, body, h, p),
                        Notifier.render(ch, pr, u, title, body, h, p), ctx);
                checked++;
            }
        assertTrue(checked > 100_000, "grid too small: " + checked);
    }

    @Test
    void titleBodyCrossProductMatchesLegacyForValidInputs() {
        for (String ch : List.of("email", "sms", "push", "slack")) for (String pr : List.of("low", "normal", "high"))
            for (String title : TEXTS) for (String body : TEXTS) for (int h : new int[] {3, 12}) {
                assertEquals(LegacyNotifier.render(ch, pr, "u", title, body, h, null),
                        Notifier.render(ch, pr, "u", title, body, h, null),
                        ch + "/" + pr + "/" + title + "/" + body + "/" + h);
            }
    }

    @Test
    void mutatedPrefsMapIsReadOnlyOnce() {
        Map<String, String> prefs = new HashMap<>();
        prefs.put("sms", "off");
        assertEquals("SKIP:disabled", Notifier.render("sms", null, "u", "t", "b", 12, prefs));
        prefs.put("sms", "on");
        assertEquals("SMS to=u text=t: b", Notifier.render("sms", null, "u", "t", "b", 12, prefs));
        assertEquals(Map.of("sms", "on"), prefs);
    }

    @Test
    void typedOutcomesExposeCategory() {
        assertInstanceOf(Outcome.Failed.class, Notifier.dispatch("fax", null, "u", "t", "b", 1, null));
        assertInstanceOf(Outcome.Skipped.class, Notifier.dispatch("sms", null, "u", "t", "b", 1, null));
        Outcome sent = Notifier.dispatch("slack", "high", "u", "t", "b", 1, null);
        assertInstanceOf(Outcome.Sent.class, sent);
        assertEquals("SLACK to=#u text=:rotating_light: *t*\nb", sent.text());
    }

    @Test
    void channelsAreDiscoverableByNameAndTruncationHelperWorks() {
        assertEquals("sms", Channel.byName("sms").orElseThrow().name());
        assertTrue(Channel.byName("SMS").isEmpty(), "lookup expects normalised names");
        assertEquals("abcdefg", Text.truncate("abcdefg", 7));
        assertEquals("abcd...", Text.truncate("abcdefgh", 7));
    }
}

package ae.notify;

import java.util.Map;

/** The messy original. Kept unchanged as the oracle for the refactoring. */
final class LegacyNotifier {
    private LegacyNotifier() {}

    static String render(String channel, String priority, String user, String title, String body,
                         int hour, Map<String, String> prefs) {
        if (channel == null || channel.trim().isEmpty()) {
            return "ERR:no-channel";
        }
        String ch = channel.trim().toLowerCase(java.util.Locale.ROOT);
        if (user == null || user.trim().isEmpty()) {
            return "ERR:no-user";
        }
        String pr;
        if (priority == null) {
            pr = "normal";
        } else {
            pr = priority.trim().toLowerCase(java.util.Locale.ROOT);
            if (!pr.equals("low") && !pr.equals("normal") && !pr.equals("high")) {
                return "ERR:bad-priority";
            }
        }
        if (hour < 0 || hour > 23) {
            return "ERR:bad-hour";
        }
        if (!ch.equals("email") && !ch.equals("sms") && !ch.equals("push") && !ch.equals("slack")) {
            return "ERR:unknown-channel:" + ch;
        }
        String u = user.trim();
        String t = title == null ? "" : title;
        String b = body == null ? "" : body;
        if (prefs != null) {
            String p = prefs.get(ch);
            if (p != null && p.trim().equalsIgnoreCase("off")) {
                return "SKIP:disabled";
            }
        }
        boolean quiet = hour >= 22 || hour < 7;
        if (quiet && !pr.equals("high")) {
            if (ch.equals("sms") || ch.equals("push")) {
                return "SKIP:quiet-hours";
            }
        }
        if (ch.equals("email")) {
            String subject = t.isEmpty() ? "(no subject)" : t;
            if (pr.equals("high")) {
                subject = "[URGENT] " + subject;
            } else if (pr.equals("low")) {
                subject = "[FYI] " + subject;
            }
            return "EMAIL to=" + u + " subject=" + subject + " body=" + b;
        } else if (ch.equals("sms")) {
            String text = t.isEmpty() ? b : (b.isEmpty() ? t : t + ": " + b);
            if (pr.equals("high")) {
                text = "!! " + text;
            }
            if (text.length() > 160) {
                text = text.substring(0, 157) + "...";
            }
            return "SMS to=" + u + " text=" + text;
        } else if (ch.equals("push")) {
            String pt = t.isEmpty() ? "(no title)" : t;
            if (pt.length() > 40) {
                pt = pt.substring(0, 37) + "...";
            }
            String pb = b;
            if (pb.length() > 100) {
                pb = pb.substring(0, 97) + "...";
            }
            String sound;
            if (pr.equals("high")) {
                sound = "alarm";
            } else if (pr.equals("normal")) {
                sound = "default";
            } else {
                sound = "none";
            }
            return "PUSH to=" + u + " title=" + pt + " body=" + pb + " sound=" + sound;
        } else {
            String text = "*" + (t.isEmpty() ? "(no title)" : t) + "*";
            if (!b.isEmpty()) {
                text = text + "\n" + b;
            }
            if (pr.equals("high")) {
                text = ":rotating_light: " + text;
            }
            return "SLACK to=#" + u + " text=" + text;
        }
    }
}
